def crop(g):
    h,w=len(g),len(g[0]); cs=[i for i in range(h) if any(c for c in g[i])]; rs=[i for i in range(h) if any(c for c in g[i])]
    # bounding box of non-background object: largest connected component
    from collections import deque
    seen=[[False]*w for _ in range(h)]; best=None
    for r in range(h):
        for c in range(w):
            if not seen[r][c] and g[r][c]:
                comp={(r,c); q=deque([(r,c)])}; 
                while q:
                    x,y=q.popleft()
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            nx,ny=x+dx,y+dy
                            if 0<=nx<h and 0<=ny<w and not seen[nx][ny] and g[nx][ny]:
                                seen[nx][ny]=True; comp.add((nx,ny)); q.append((nx,ny))
                if best is None or len(comp)<len(best): best=comp
    r0=min(r for r,c in best); r1=max(r for r,c in best); c0=min(c for r,c in best); c1=max(c for r,c in best)
    return [[g[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
