from collections import deque
def bbox(g,col=None):
    h,w=g.shape; seen=np.zeros_like(g,dtype=bool); best=None
    for r in range(h):
        for c in range(w):
            col_=g[r][c]
            if g[r][c]!=0 and (col is None or col_==col and not seen[r][c]):
                comp=set(); q=deque([(r,c)]); seen[r][c]=True
                while q:
                    x,y=q.popleft()
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            nx,ny=x+dx,y+dy
                            if 0<=nx<h and 0<=ny<w and g[nx][ny]==col and not seen[nx][ny]:
                                seen[nx][ny]=True; comp.add((nx,ny)); q.append((nx,ny))
                if best is None or len(comp)>len(best): best=comp
    return best
