def analyze(key):
    I=np.array(G[key+' input']); O=np.array(G[key+' output'])
    cnt=Counter(I.flatten()); bg=cnt.most_common(1)[0][0]
    cc=comps(I.tolist(),1); best=max(cc,key=lambda c:len(c)); lg=list(best)
    rs=[i for i,_ in lg]; cs=[j for _,j in lg]
    S=I[min(rs):max(rs)+1,min(cs):max(cs)+1]
    h,w=S.shape; M=S!=1
    cands={'id':M,'fliplr':M[:,::-1],'flipud':M[::-1,:],'rot180':M[::-1,::-1],
           'rot90':np.rot90(M),'rot90_anti':np.rot90(M,-1),'T':M.T,'antiT':M.T[:,::-1]}
    scores={}
    for vn,V in cands.items():
        # auto-overlap: max correlation of V with itself shifted - measure symmetry
        bestcorr=0
        H,W=V.shape
        for dr in range(H):
