        scores[vn]=(bestcorr,(H,W)==(O.shape[0],O.shape[1]) and np.array_equal(V,O))
    print(key,'S',S.shape,'O',O.shape)
    for k,v in sorted(scores.items(),key=lambda x:-x[1][0]): print('  ',k,'sym',round(v[0],3),'exact',v[1])
